class FontMock {
    constructor(name, size) {
        this.name = name;
        this.size = size;
        this.height = size;
    }
}

export default class Poco {
    constructor(screen) {
        this.width = 260;
        this.height = 260;
        this.Font = FontMock;
    }

    makeColor(r, g, b) {
        return { r, g, b };
    }

    begin() {}
    end() {}
    fillRectangle() {}
    drawRectangle() {}
    drawText() {}
    
    getTextWidth(text, font) {
        return text.length * 8;
    }
}
